// переводы
#[derive(Clone, Copy, PartialEq)]
pub enum Lang { En, Ru, Uk, De, Es, Fr, Pt, Pl, Tr, Zh }

impl Lang {
    pub fn from_code(c: &str) -> Option<Lang> {
        Some(match c { "en" => Lang::En, "ru" => Lang::Ru, "uk" | "ua" => Lang::Uk, "de" => Lang::De, "es" => Lang::Es, "fr" => Lang::Fr, "pt" | "br" => Lang::Pt, "pl" => Lang::Pl, "tr" => Lang::Tr, "zh" | "cn" => Lang::Zh, _ => return None })
    }
}

